INSERT INTO grammar_questions (meeting_number, section, question_number, question_text, correct_answer, tense, structure, formula, example, vocabulary) VALUES (5, 'pr', 0, 'Para arkeolog tidak menemukan artefak itu sebelum penggalian terakhir.', 'Archaeologists did not find that artifact before the last excavation', 'Simple Past', NULL, NULL, 'Columbus tidak menemukan Amerika pada 1491.|Columbus did not discover America in 1491', '{\"arkeolog\":\"archaeologist\",\"menemukan\":\"find\",\"artefak\":\"artifact\",\"penggalian\":\"excavation\"}');
INSERT INTO grammar_questions (meeting_number, section, question_number, question_text, correct_answer, tense, structure, formula, example, vocabulary) VALUES (5, 'pr', 0, 'Ilmuwan tidak sedang meneliti spesies baru di hutan Amazon.', 'Scientists are not researching new species in the Amazon forest', 'Present Continuous', NULL, NULL, 'Para peneliti tidak sedang mengamati perilaku hewan.|Researchers are not observing animal behavior', '{\"ilmuwan\":\"scientist\",\"meneliti\":\"research\",\"spesies\":\"species\",\"hutan\":\"forest\"}');
INSERT INTO grammar_questions (meeting_number, section, question_number, question_text, correct_answer, tense, structure, formula, example, vocabulary) VALUES (5, 'pr', 0, 'Teknologi tidak mengalami perkembangan yang stagnan.', 'Technology is not experiencing stagnant development', 'Simple Present', NULL, NULL, 'Ekonomi tidak mengalami pertumbuhan yang cepat.|The economy does not experience rapid growth', '{\"teknologi\":\"technology\",\"mengalami\":\"experience\",\"perkembangan\":\"development\",\"stagnan\":\"stagnant\"}');
INSERT INTO grammar_questions (meeting_number, section, question_number, question_text, correct_answer, tense, structure, formula, example, vocabulary) VALUES (5, 'pr', 0, 'Gunung berapi itu tidak pernah meletus sebelum gempa.', 'That volcano had never erupted before the earthquake', 'Past Perfect', NULL, NULL, 'Manusia belum pernah melihat fenomena itu sebelumnya.|Humans had never seen that phenomenon before', '{\"gunung berapi\":\"volcano\",\"meletus\":\"erupt\",\"gempa\":\"earthquake\"}');
INSERT INTO grammar_questions (meeting_number, section, question_number, question_text, correct_answer, tense, structure, formula, example, vocabulary) VALUES (5, 'pr', 0, 'Para astronom tidak sedang mengamati bintang jatuh tadi malam.', 'Astronomers were not observing shooting stars last night', 'Past Continuous', NULL, NULL, 'Ilmuwan tidak sedang melakukan eksperimen kemarin.|Scientists were not conducting experiments yesterday', '{\"astronom\":\"astronomer\",\"mengamati\":\"observe\",\"bintang jatuh\":\"shooting star\"}');
INSERT INTO grammar_questions (meeting_number, section, question_number, question_text, correct_answer, tense, structure, formula, example, vocabulary) VALUES (5, 'pr', 0, 'Ilmuwan tidak pernah menemukan fosil dinosaurus hidup.', 'Scientists have never found living dinosaur fossils', 'Present Perfect', NULL, NULL, 'Peneliti belum menemukan bukti kehidupan di Mars.|Researchers have not found evidence of life on Mars', '{\"ilmuwan\":\"scientist\",\"menemukan\":\"find\",\"fosil\":\"fossil\",\"dinosaurus\":\"dinosaur\"}');
INSERT INTO grammar_questions (meeting_number, section, question_number, question_text, correct_answer, tense, structure, formula, example, vocabulary) VALUES (5, 'pr', 0, 'Tim penyelamat tidak sedang mencari korban di lokasi bencana.', 'The rescue team is not searching for victims at the disaster location', 'Present Continuous', NULL, NULL, 'Petugas tidak sedang mengevakuasi warga.|Officers are not evacuating residents', '{\"penyelamat\":\"rescue\",\"mencari\":\"search\",\"korban\":\"victim\",\"bencana\":\"disaster\"}');
INSERT INTO grammar_questions (meeting_number, section, question_number, question_text, correct_answer, tense, structure, formula, example, vocabulary) VALUES (5, 'pr', 0, 'Para insinyur tidak sedang menguji mesin baru minggu lalu.', 'Engineers were not testing the new machine last week', 'Past Continuous', NULL, NULL, 'Teknisi tidak sedang memperbaiki sistem kemarin.|Technicians were not repairing the system yesterday', '{\"insinyur\":\"engineer\",\"menguji\":\"test\",\"mesin\":\"machine\"}');
INSERT INTO grammar_questions (meeting_number, section, question_number, question_text, correct_answer, tense, structure, formula, example, vocabulary) VALUES (5, 'pr', 0, 'Pekerja tidak sedang membangun jembatan di kota itu bulan lalu.', 'Workers were not building a bridge in that city last month', 'Past Continuous', NULL, NULL, 'Kontraktor tidak sedang merenovasi gedung tahun lalu.|Contractors were not renovating the building last year', '{\"pekerja\":\"worker\",\"membangun\":\"build\",\"jembatan\":\"bridge\"}');
INSERT INTO grammar_questions (meeting_number, section, question_number, question_text, correct_answer, tense, structure, formula, example, vocabulary) VALUES (5, 'pr', 0, 'Dokter tidak pernah menemukan obat untuk penyakit langka itu sebelumnya.', 'Doctors had never found a cure for that rare disease before', 'Past Perfect', NULL, NULL, 'Peneliti belum menemukan vaksin untuk virus itu sebelumnya.|Researchers had not found a vaccine for that virus before', '{\"dokter\":\"doctor\",\"menemukan\":\"find\",\"obat\":\"cure\",\"penyakit\":\"disease\"}');
